package com.cc91.service;

import com.cc91.dto.CommentResponse;
import com.cc91.dto.CreateCommentRequest;
import com.cc91.dto.UserCommentResponse;
import com.cc91.entity.Comment;
import com.cc91.entity.Post;
import com.cc91.entity.User;
import com.cc91.exception.ResourceNotFoundException;
import com.cc91.exception.UnauthorizedException;
import com.cc91.repository.CommentRepository;
import com.cc91.repository.PostRepository;
import com.cc91.repository.UserRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.*;
import java.util.stream.Collectors;

/**
 * 评论服务
 */
@Service
public class CommentService {

    private static final Logger logger = LoggerFactory.getLogger(CommentService.class);

    private final CommentRepository commentRepository;
    private final PostRepository postRepository;
    private final UserRepository userRepository;
    private final NotificationService notificationService;

    public CommentService(CommentRepository commentRepository,
                         PostRepository postRepository,
                         UserRepository userRepository,
                         NotificationService notificationService) {
        this.commentRepository = commentRepository;
        this.postRepository = postRepository;
        this.userRepository = userRepository;
        this.notificationService = notificationService;
    }

    /**
     * 创建评论
     */
    @Transactional
    public CommentResponse createComment(String username, Long postId, CreateCommentRequest request) {
        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new ResourceNotFoundException("用户不存在"));

        Post post = postRepository.findById(postId)
                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));

        Comment comment = new Comment(postId, user.getId(), request.getContent(), null);
        comment = commentRepository.save(comment);

        // 如果评论的不是自己的帖子，通知帖子作者
        if (!post.getAuthorId().equals(user.getId())) {
            User postAuthor = userRepository.findById(post.getAuthorId()).orElse(null);
            if (postAuthor != null) {
                notificationService.createNotification(
                        post.getAuthorId(),
                        "REPLY",
                        "新评论通知",
                        user.getUsername() + " 评论了你的帖子: " + post.getTitle(),
                        comment.getId()
                );
            }
        }

        logger.info("评论创建成功: id={}, postId={}, author={}", comment.getId(), postId, username);

        return toCommentResponse(comment, user.getUsername());
    }

    /**
     * 回复评论
     */
    @Transactional
    public CommentResponse replyToComment(String username, Long commentId, CreateCommentRequest request) {
        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new ResourceNotFoundException("用户不存在"));

        Comment parentComment = commentRepository.findById(commentId)
                .orElseThrow(() -> new ResourceNotFoundException("评论不存在"));

        Comment reply = new Comment(parentComment.getPostId(), user.getId(),
                                    request.getContent(), commentId);
        reply = commentRepository.save(reply);

        // 通知被回复的评论作者（如果不是自己回复自己）
        if (!parentComment.getAuthorId().equals(user.getId())) {
            User parentAuthor = userRepository.findById(parentComment.getAuthorId()).orElse(null);
            if (parentAuthor != null) {
                Post post = postRepository.findById(parentComment.getPostId()).orElse(null);
                String postTitle = post != null ? post.getTitle() : "未知帖子";
                notificationService.createNotification(
                        parentComment.getAuthorId(),
                        "REPLY",
                        "新回复通知",
                        user.getUsername() + " 回复了你在「" + postTitle + "」中的评论",
                        reply.getId()
                );
            }
        }

        logger.info("回复评论成功: id={}, parentId={}, author={}", reply.getId(), commentId, username);

        return toCommentResponse(reply, user.getUsername());
    }

    /**
     * 删除评论（软删除）
     */
    @Transactional
    public void deleteComment(String username, Long commentId) {
        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new ResourceNotFoundException("用户不存在"));

        Comment comment = commentRepository.findById(commentId)
                .orElseThrow(() -> new ResourceNotFoundException("评论不存在"));

        // 验证作者权限
        if (!comment.getAuthorId().equals(user.getId())) {
            throw new UnauthorizedException("无权限删除此评论");
        }

        // 软删除该评论及其所有子评论
        comment.setStatus("DELETED");
        commentRepository.save(comment);

        // 同时软删除所有子评论
        List<Comment> replies = commentRepository.findByParentIdOrderByCreatedAtAsc(commentId);
        for (Comment reply : replies) {
            reply.setStatus("DELETED");
        }
        commentRepository.saveAll(replies);

        logger.info("评论删除成功: id={}, 关联子评论数={}, author={}", commentId, replies.size(), username);
    }

    /**
     * 获取帖子的所有评论（树形结构）
     */
    @Transactional(readOnly = true)
    public List<CommentResponse> getCommentsByPostId(Long postId) {
        Post post = postRepository.findById(postId)
                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));

        // 查询所有已发布的评论
        List<Comment> comments = commentRepository.findByPostIdAndStatusOrderByCreatedAtAsc(postId, "PUBLISHED");

        // 批量查询所有相关用户
        Set<Long> authorIds = comments.stream()
                .map(Comment::getAuthorId)
                .collect(Collectors.toSet());

        Map<Long, String> userMap = userRepository.findAllById(authorIds).stream()
                .collect(Collectors.toMap(User::getId, User::getUsername));

        // 构建树形结构
        return buildCommentTree(comments, userMap);
    }

        /**
         * 获取当前用户的评论列表（用于 Dashboard "我的评论"）
         */
        @Transactional(readOnly = true)
        public List<UserCommentResponse> getMyComments(String username) {
        User user = userRepository.findByUsername(username)
            .orElseThrow(() -> new ResourceNotFoundException("用户不存在"));

        List<Comment> comments = commentRepository.findByAuthorIdAndStatusOrderByCreatedAtDesc(user.getId(), "PUBLISHED");
        if (comments.isEmpty()) {
            return Collections.emptyList();
        }

        Set<Long> postIds = comments.stream()
            .map(Comment::getPostId)
            .collect(Collectors.toSet());

        Map<Long, String> postTitleMap = postRepository.findAllById(postIds).stream()
            .collect(Collectors.toMap(Post::getId, Post::getTitle));

        return comments.stream()
            .map(c -> new UserCommentResponse(
                c.getId(),
                c.getPostId(),
                postTitleMap.getOrDefault(c.getPostId(), "未知帖子"),
                c.getContent(),
                c.getParentId(),
                c.getCreatedAt(),
                c.getStatus()
            ))
            .collect(Collectors.toList());
        }

    /**
     * 构建评论树形结构
     */
    private List<CommentResponse> buildCommentTree(List<Comment> comments, Map<Long, String> userMap) {
        // 转换为 CommentResponse
        List<CommentResponse> responses = comments.stream()
                .map(comment -> toCommentResponse(comment, userMap.get(comment.getAuthorId())))
                .collect(Collectors.toList());

        // 构建 ID 到 Response 的映射
        Map<Long, CommentResponse> responseMap = new HashMap<>();
        for (CommentResponse response : responses) {
            responseMap.put(response.getId(), response);
        }

        // 构建树形结构
        List<CommentResponse> rootComments = new ArrayList<>();
        for (CommentResponse response : responses) {
            if (response.getParentId() == null) {
                // 顶级评论
                rootComments.add(response);
            } else {
                // 子评论，添加到父评论的 replies 中
                CommentResponse parent = responseMap.get(response.getParentId());
                if (parent != null) {
                    parent.getReplies().add(response);
                }
            }
        }

        return rootComments;
    }

    /**
     * 转换为 CommentResponse
     */
    private CommentResponse toCommentResponse(Comment comment, String authorUsername) {
        return new CommentResponse(
                comment.getId(),
                comment.getPostId(),
                comment.getAuthorId(),
                authorUsername,
                comment.getContent(),
                comment.getParentId(),
                comment.getCreatedAt(),
                comment.getStatus()
        );
    }
}

package com.cc91.service;

import com.cc91.dto.CreatePostRequest;
import com.cc91.dto.PostResponse;
import com.cc91.dto.UpdatePostRequest;
import com.cc91.entity.Category;
import com.cc91.entity.Post;
import com.cc91.entity.User;
import com.cc91.exception.ResourceNotFoundException;
import com.cc91.exception.UnauthorizedException;
import com.cc91.repository.PostRepository;
import com.cc91.repository.UserRepository;
import com.cc91.repository.CategoryRepository;
import com.cc91.repository.CommentRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Pageable;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.*;
import java.util.stream.Collectors;

/**
 * 帖子服务
 */
@Service
public class PostService {

    private static final Logger logger = LoggerFactory.getLogger(PostService.class);

    private final PostRepository postRepository;
    private final UserRepository userRepository;
    private final CategoryRepository categoryRepository;
    private final CommentRepository commentRepository;

    public PostService(PostRepository postRepository, UserRepository userRepository, CategoryRepository categoryRepository, CommentRepository commentRepository) {
        this.postRepository = postRepository;
        this.userRepository = userRepository;
        this.categoryRepository = categoryRepository;
        this.commentRepository = commentRepository;
    }

    /**
     * 创建帖子
     */
    @Transactional
    public PostResponse createPost(String username, CreatePostRequest request) {
        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new ResourceNotFoundException("用户不存在"));

        Post post = new Post(request.getTitle(), request.getContent(), user.getId());
        post.setCategoryId(request.getCategoryId());
        if (request.getStatus() != null) {
            post.setStatus(request.getStatus());
        }
        post = postRepository.save(post);

        logger.info("帖子创建成功: id={}, author={}", post.getId(), username);

        return toPostResponse(post, user.getUsername());
    }

    /**
     * 获取帖子详情（增加浏览次数）
     */
    @Transactional
    public PostResponse getPostById(Long id) {
        Post post = postRepository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));

        // 增加浏览次数
        post.setViewCount(post.getViewCount() + 1);
        postRepository.save(post);

        User author = userRepository.findById(post.getAuthorId())
                .orElseThrow(() -> new ResourceNotFoundException("作者不存在"));

        return toPostResponse(post, author.getUsername());
    }

    /**
     * 根据版块ID分页查询帖子
     */
    @Transactional(readOnly = true)
    public Page<PostResponse> getPostsByCategory(Long categoryId, int page, int size) {
        // 验证版块是否存在
        if (!categoryRepository.existsById(categoryId)) {
            throw new ResourceNotFoundException("版块不存在");
        }

        Pageable pageable = PageRequest.of(page, size, Sort.by(Sort.Direction.DESC, "createdAt"));
        Page<Post> posts = postRepository.findByCategoryIdAndStatus(categoryId, "PUBLISHED", pageable);

        return toPostResponsePage(posts);
    }

    /**
     * 更新帖子
     */
    @Transactional
    public PostResponse updatePost(String username, Long postId, UpdatePostRequest request) {
        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new ResourceNotFoundException("用户不存在"));

        Post post = postRepository.findById(postId)
                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));

        // 验证作者权限
        if (!post.getAuthorId().equals(user.getId())) {
            throw new UnauthorizedException("无权限编辑此帖子");
        }

        // 更新字段
        if (request.getTitle() != null) {
            post.setTitle(request.getTitle());
        }
        if (request.getContent() != null) {
            post.setContent(request.getContent());
        }
        if (request.getCategoryId() != null) {
            // 验证版块是否存在
            if (!categoryRepository.existsById(request.getCategoryId())) {
                throw new ResourceNotFoundException("版块不存在");
            }
            post.setCategoryId(request.getCategoryId());
        }

        post = postRepository.save(post);

        logger.info("帖子更新成功: id={}, author={}", postId, username);

        return toPostResponse(post, user.getUsername());
    }

    /**
     * 删除帖子
     */
    @Transactional
    public void deletePost(String username, Long postId) {
        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new ResourceNotFoundException("用户不存在"));

        Post post = postRepository.findById(postId)
                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));

        // 验证作者权限
        if (!post.getAuthorId().equals(user.getId())) {
            throw new UnauthorizedException("无权限删除此帖子");
        }

        postRepository.delete(post);

        logger.info("帖子删除成功: id={}, author={}", postId, username);
    }

    /**
     * 分页查询帖子列表
     */
    @Transactional(readOnly = true)
    public Page<PostResponse> getPostList(int page, int size, String status) {
        Pageable pageable = PageRequest.of(page, size, Sort.by(Sort.Direction.DESC, "createdAt"));
        Page<Post> posts;
        if (status == null || status.trim().isEmpty()) {
            posts = postRepository.findAll(pageable);
        } else {
            posts = postRepository.findByStatus(status, pageable);
        }

        return toPostResponsePage(posts);
    }

    /**
     * 获取当前用户的帖子列表（用于 Dashboard "我的帖子"）
     */
    @Transactional(readOnly = true)
    public List<PostResponse> getMyPosts(String username) {
        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new ResourceNotFoundException("用户不存在"));

        List<Post> posts = postRepository.findByAuthorIdOrderByCreatedAtDesc(user.getId());
        if (posts.isEmpty()) {
            return Collections.emptyList();
        }

        return toPostResponseList(posts);
    }

    /**
     * 搜索帖子（按标题或内容）
     */
    @Transactional(readOnly = true)
    public Page<PostResponse> searchPosts(String keyword, int page, int size) {
        // 空关键词返回空结果
        if (keyword == null || keyword.trim().isEmpty()) {
            return Page.empty();
        }

        String trimmedKeyword = keyword.trim();
        Pageable pageable = PageRequest.of(page, size, Sort.by(Sort.Direction.DESC, "createdAt"));

        // 搜索标题或内容包含关键词的已发布帖子
        Page<Post> posts = postRepository.findByStatusAndTitleContainingOrStatusAndContentContaining(
                "PUBLISHED", trimmedKeyword,
                "PUBLISHED", trimmedKeyword,
                pageable
        );

        return toPostResponsePage(posts);
    }

    /**
     * 批量转换 Post Page 为 PostResponse Page（解决 N+1 查询问题）
     */
    private Page<PostResponse> toPostResponsePage(Page<Post> posts) {
        List<Post> postList = posts.getContent();

        // 批量收集所有需要的 id
        Set<Long> authorIds = postList.stream()
                .map(Post::getAuthorId)
                .collect(Collectors.toSet());

        Set<Long> categoryIds = postList.stream()
                .map(Post::getCategoryId)
                .filter(Objects::nonNull)
                .collect(Collectors.toSet());

        Set<Long> postIds = postList.stream()
                .map(Post::getId)
                .collect(Collectors.toSet());

        // 批量查询用户
        Map<Long, User> userMap = userRepository.findAllById(authorIds).stream()
                .collect(Collectors.toMap(User::getId, u -> u));

        // 批量查询分类
        Map<Long, Category> categoryMap = categoryIds.isEmpty()
                ? Collections.emptyMap()
                : categoryRepository.findAllById(categoryIds).stream()
                        .collect(Collectors.toMap(Category::getId, c -> c));

        // 批量查询评论数
        Map<Long, Long> commentCountMap = new HashMap<>();
        for (Long postId : postIds) {
            commentCountMap.put(postId, commentRepository.countByPostIdAndStatus(postId, "PUBLISHED"));
        }

        return posts.map(post -> {
            User author = userMap.get(post.getAuthorId());
            String authorUsername = author != null ? author.getUsername() : "未知用户";

            String categoryName = null;
            if (post.getCategoryId() != null) {
                Category category = categoryMap.get(post.getCategoryId());
                categoryName = category != null ? category.getName() : null;
            }

            long commentCount = commentCountMap.getOrDefault(post.getId(), 0L);

            return new PostResponse(
                    post.getId(),
                    post.getTitle(),
                    post.getContent(),
                    post.getAuthorId(),
                    authorUsername,
                    post.getCategoryId(),
                    categoryName,
                    post.getCreatedAt(),
                    post.getUpdatedAt(),
                    post.getViewCount(),
                    post.getStatus(),
                    commentCount
            );
        });
    }

        /**
         * 批量转换 Post List 为 PostResponse List（解决 N+1 查询问题）
         */
        private List<PostResponse> toPostResponseList(List<Post> postList) {
        // 批量收集所有需要的 id
        Set<Long> authorIds = postList.stream()
