import { BrowserRouter, Routes, Route, Outlet } from 'react-router-dom';
import { QueryClientProvider } from '@tanstack/react-query';
import { AuthProvider, useAuth } from './context/AuthContext';
import ProtectedRoute from './components/ProtectedRoute';
import AdminRoute from './components/AdminRoute';
import Layout from './components/Layout';
import AdminLayout from './components/AdminLayout';
import HomePage from './pages/HomePage';
import LoginPage from './pages/LoginPage';
import RegisterPage from './pages/RegisterPage';
import DashboardPage from './pages/DashboardPage';
import MyPostsPage from './pages/MyPostsPage';
import MyCommentsPage from './pages/MyCommentsPage';
import ProfilePage from './pages/ProfilePage';
import ProfileEditPage from './pages/ProfileEditPage';
import PostListPage from './pages/PostListPage';
import PostDetailPage from './pages/PostDetailPage';
import CreatePostPage from './pages/CreatePostPage';
import EditPostPage from './pages/EditPostPage';
import CategoryPage from './pages/CategoryPage';
import ForgotPasswordPage from './pages/ForgotPasswordPage';
import ResetPasswordPage from './pages/ResetPasswordPage';
import SearchPage from './pages/SearchPage';
import NotificationsPage from './pages/NotificationsPage';
import NotFoundPage from './pages/NotFoundPage';
import AdminDashboard from './pages/admin/AdminDashboard';
import CategoryManage from './pages/admin/CategoryManage';
import ContentModeration from './pages/admin/ContentModeration';
import UserManage from './pages/admin/UserManage';
import { queryClient } from './lib/queryClient';

function AdminRoutes() {
  const { isAdmin } = useAuth();
  return (
    <AdminRoute isAdmin={isAdmin}>
      <AdminLayout />
    </AdminRoute>
  );
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <BrowserRouter>
        <AuthProvider>
          <Routes>
            <Route path="/" element={<Layout><Outlet /></Layout>}>
              <Route index element={<HomePage />} />
              <Route path="login" element={<LoginPage />} />
              <Route path="register" element={<RegisterPage />} />
              <Route path="forgot-password" element={<ForgotPasswordPage />} />
              <Route path="reset-password" element={<ResetPasswordPage />} />
              <Route path="profile/:username" element={<ProfilePage />} />
              <Route
                path="profile/edit"
                element={
                  <ProtectedRoute>
                    <ProfileEditPage />
                  </ProtectedRoute>
                }
              />
              <Route
                path="dashboard"
                element={
                  <ProtectedRoute>
                    <DashboardPage />
                  </ProtectedRoute>
                }
              />

              <Route
                path="dashboard/posts"
                element={
                  <ProtectedRoute>
                    <MyPostsPage />
                  </ProtectedRoute>
                }
              />

              <Route
                path="dashboard/comments"
                element={
                  <ProtectedRoute>
                    <MyCommentsPage />
                  </ProtectedRoute>
                }
              />

              {/* 版块相关路由 */}
              <Route path="category/:id" element={<CategoryPage />} />

              {/* 帖子相关路由 */}
              <Route path="posts" element={<PostListPage />} />
              <Route path="posts/:id" element={<PostDetailPage />} />
              <Route
                path="posts/new"
                element={
                  <ProtectedRoute>
                    <CreatePostPage />
                  </ProtectedRoute>
                }
              />
              <Route
                path="posts/:id/edit"
                element={
                  <ProtectedRoute>
                    <EditPostPage />
                  </ProtectedRoute>
                }
              />

              {/* 搜索和通知路由 */}
              <Route path="search" element={<SearchPage />} />
              <Route
                path="notifications"
                element={
                  <ProtectedRoute>
                    <NotificationsPage />
                  </ProtectedRoute>
                }
              />

              {/* 404 */}
              <Route path="*" element={<NotFoundPage />} />
            </Route>

            {/* 管理后台路由 */}
            <Route path="/admin" element={
              <ProtectedRoute>
                <AdminRoutes />
              </ProtectedRoute>
            }>
              <Route index element={<AdminDashboard />} />
              <Route path="categories" element={<CategoryManage />} />
              <Route path="content" element={<ContentModeration />} />
              <Route path="users" element={<UserManage />} />

              {/* 404 */}
              <Route path="*" element={<NotFoundPage />} />
            </Route>
          </Routes>
        </AuthProvider>
      </BrowserRouter>
    </QueryClientProvider>
  );
}

export default App;

import { useNavigate } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import { useAuth } from '../context/AuthContext';
import { getMyPosts } from '../api/user';
import { queryKeys } from '../lib/queryKeys';
import { formatDate } from '../utils/formatDate';

/**
 * 我的帖子页面
 */
export default function MyPostsPage() {
  const { user } = useAuth();
  const navigate = useNavigate();

  const { data: myPosts = [], isLoading, error } = useQuery({
    queryKey: queryKeys.users.mePosts(),
    queryFn: () => getMyPosts(),
    enabled: !!user,
  });

  return (
    <div className="container" style={{ maxWidth: '900px', padding: '2rem' }}>
      <button onClick={() => navigate('/dashboard')} className="btn" style={{ marginBottom: '1rem' }}>
        &larr; 返回 Dashboard
      </button>

      <div className="card" style={{ padding: '1.5rem' }}>
        <h1 style={{ marginBottom: '1rem' }}>📝 我的帖子</h1>

        {isLoading ? (
          <div style={{ textAlign: 'center', padding: '1rem', color: '#999' }}>加载中...</div>
        ) : error ? (
          <div className="error-message" role="alert">
            {(error as any)?.response?.data?.message || '加载失败'}
          </div>
        ) : myPosts.length === 0 ? (
          <div className="empty-state">你还没有发布帖子</div>
        ) : (
          <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
            {myPosts.map((post) => (
              <li
                key={post.id}
                className="post-item"
                role="button"
                tabIndex={0}
                onClick={() => navigate(`/posts/${post.id}`)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    navigate(`/posts/${post.id}`);
                  }
                }}
                style={{
                  padding: '0.75rem 0',
                  borderBottom: '1px solid #eee',
                  cursor: 'pointer'
                }}
                aria-label={`查看帖子：${post.title}`}
              >
                <div style={{ fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                  {post.title}
                </div>
                <div style={{ fontSize: '0.85rem', color: '#999', display: 'flex', gap: '0.75rem', marginTop: '0.25rem' }}>
                  <span><time dateTime={post.createdAt}>{formatDate(post.createdAt)}</time></span>
                  {post.status && <span>{post.status}</span>}
                  <span>评论 {post.commentCount ?? 0}</span>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

