            ) : myCommentsError ? (
              <div className="error-message" role="alert">
                {(myCommentsError as any)?.response?.data?.message || '加载失败'}
              </div>
            ) : myComments.length === 0 ? (
              <div className="empty-state">你还没有发表过评论</div>
            ) : (
              <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
                {myComments.slice(0, 5).map((c) => (
                  <li
                    key={c.id}
                    role="button"
                    tabIndex={0}
                    onClick={() => navigate(`/posts/${c.postId}`)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        navigate(`/posts/${c.postId}`);
                      }
                    }}
                    style={{
                      padding: '0.75rem 0',
                      borderBottom: '1px solid #eee',
                      cursor: 'pointer'
                    }}
                    aria-label={`查看评论对应帖子：${c.postTitle}`}
                  >
                    <div style={{ fontSize: '0.9rem', color: '#333', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                      {c.content}
                    </div>
                    <div style={{ fontSize: '0.85rem', color: '#999', marginTop: '0.25rem', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                      <span style={{ marginRight: '0.5rem' }}>
                        <time dateTime={c.createdAt}>{formatDate(c.createdAt)}</time>
                      </span>
                      <span>来自：{c.postTitle}</span>
                    </div>
                  </li>
                ))}
              </ul>
            )}

            <button
              className="btn"
              onClick={() => navigate('/dashboard/comments')}
              style={{ width: '100%', marginTop: '1rem' }}
            >
              查看所有评论
            </button>
          </div>
        </div>

        {/* 右侧：最新通知 */}
        <div>
          <div className="card" style={{ padding: '1.5rem' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
              <h2 style={{ margin: 0 }}>🔔 最新通知</h2>
              {unreadCount > 0 && (
                <span style={{
                  background: '#e74c3c',
                  color: '#fff',
                  padding: '0.25rem 0.5rem',
                  borderRadius: '10px',
                  fontSize: '0.8rem'
                }}>
                  {unreadCount} 条未读
                </span>
              )}
            </div>

            {notificationsLoading ? (
              <div style={{ textAlign: 'center', padding: '1rem', color: '#999' }}>加载中...</div>
            ) : recentNotifications.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '1rem', color: '#999' }}>暂无通知</div>
            ) : (
              <ul style={{ listStyle: 'none', padding: 0 }}>
                {recentNotifications.map((notif) => (
                  <li
                    key={notif.id}
                    style={{
                      padding: '0.75rem 0',
                      borderBottom: '1px solid #eee',
                      cursor: 'pointer'
                    }}
                    onClick={() => {
                      if (notif.relatedId) {
                        navigate(`/posts/${notif.relatedId}`);
                      }
                    }}
                  >
                    <div style={{ display: 'flex', alignItems: 'flex-start' }}>
                      <span style={{ marginRight: '0.5rem' }}>
                        {notif.type === 'REPLY' ? '💬' : '🔔'}
                      </span>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{
                          fontWeight: notif.isRead ? 'normal' : '600',
                          fontSize: '0.9rem',
                          overflow: 'hidden',
                          textOverflow: 'ellipsis',
                          whiteSpace: 'nowrap'
                        }}>
                          {notif.title}
                        </div>
                        <div style={{
                          fontSize: '0.8rem',
                          color: '#999',
                          overflow: 'hidden',
                          textOverflow: 'ellipsis',
                          whiteSpace: 'nowrap'
                        }}>
                          {notif.content}
                        </div>
                      </div>
                    </div>
                  </li>
                ))}
              </ul>
            )}

            <button
              className="btn"
              onClick={() => navigate('/notifications')}
              style={{ width: '100%', marginTop: '1rem' }}
            >
              查看全部通知
            </button>
          </div>
        </div>
      </div>

      {/* 退出登录 */}
      <div style={{ marginTop: '2rem', textAlign: 'center' }}>
        <button
          onClick={logout}
          className="btn btn-danger"
        >
          退出登录
        </button>
      </div>
    </div>
  );
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MemoryRouter } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { AuthProvider } from '../../context/AuthContext';
import DashboardPage from '../../pages/DashboardPage';
import * as notificationApi from '../../api/notification';
import * as userApi from '../../api/user';

vi.mock('../../api/notification');
vi.mock('../../api/user');

const mockNavigate = vi.fn();
vi.mock('react-router-dom', async () => ({
  ...(await vi.importActual('react-router-dom')),
  useNavigate: () => mockNavigate,
}));

describe('DashboardPage', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    localStorage.clear();
    localStorage.setItem('access_token', 'test-token');
    localStorage.setItem('user', JSON.stringify({ username: 'testuser', email: 'test@example.com' }));
  });

  const createWrapper = () => {
    const queryClient = new QueryClient({
      defaultOptions: {
        queries: { retry: false, gcTime: 0 },
        mutations: { retry: false },
      },
    });

    return function Wrapper({ children }: { children: React.ReactNode }) {
      return (
        <QueryClientProvider client={queryClient}>
          <MemoryRouter>
            <AuthProvider>{children}</AuthProvider>
          </MemoryRouter>
        </QueryClientProvider>
      );
    };
  };

  it('应该渲染我的帖子与我的评论列表', async () => {
    vi.mocked(notificationApi.getNotifications).mockResolvedValue([]);
    vi.mocked(notificationApi.getUnreadCount).mockResolvedValue(0);

    vi.mocked(userApi.getMyPosts).mockResolvedValue([
      {
        id: 1,
        title: 'My Post 1',
        content: 'content',
        authorId: 1,
        authorUsername: 'testuser',
        createdAt: '2024-01-02T10:00:00',
        updatedAt: '2024-01-02T10:00:00',
        viewCount: 0,
        commentCount: 2,
        status: 'PUBLISHED',
      },
    ]);

    vi.mocked(userApi.getMyComments).mockResolvedValue([
      {
        id: 11,
        postId: 1,
        postTitle: 'My Post 1',
        content: 'My Comment 1',
        parentId: null,
        createdAt: '2024-01-03T10:00:00',
        status: 'PUBLISHED',
      },
    ]);

    render(<DashboardPage />, { wrapper: createWrapper() });

    await waitFor(() => {
      expect(screen.getByText('My Post 1')).toBeInTheDocument();
      expect(screen.getByText('My Comment 1')).toBeInTheDocument();
      expect(screen.getByText('来自：My Post 1')).toBeInTheDocument();
    });
  });

  it('点击评论应跳转到对应帖子详情页', async () => {
    const user = userEvent.setup();

    vi.mocked(notificationApi.getNotifications).mockResolvedValue([]);
    vi.mocked(notificationApi.getUnreadCount).mockResolvedValue(0);
    vi.mocked(userApi.getMyPosts).mockResolvedValue([]);
    vi.mocked(userApi.getMyComments).mockResolvedValue([
      {
        id: 99,
        postId: 123,
        postTitle: 'Target Post',
        content: 'Jump Comment',
        parentId: null,
        createdAt: '2024-01-03T10:00:00',
        status: 'PUBLISHED',
      },
    ]);

    render(<DashboardPage />, { wrapper: createWrapper() });

    const commentRow = await screen.findByText('Jump Comment');
    await user.click(commentRow);

    expect(mockNavigate).toHaveBeenCalledWith('/posts/123');
  });

  it('点击查看全部帖子应跳转到我的帖子页面', async () => {
    const user = userEvent.setup();

    vi.mocked(notificationApi.getNotifications).mockResolvedValue([]);
    vi.mocked(notificationApi.getUnreadCount).mockResolvedValue(0);
    vi.mocked(userApi.getMyPosts).mockResolvedValue([]);
    vi.mocked(userApi.getMyComments).mockResolvedValue([]);

    render(<DashboardPage />, { wrapper: createWrapper() });

    const btn = await screen.findByRole('button', { name: '查看全部帖子' });
    await user.click(btn);

    expect(mockNavigate).toHaveBeenCalledWith('/dashboard/posts');
  });

  it('点击查看所有评论应跳转到我的评论页面', async () => {
    const user = userEvent.setup();

    vi.mocked(notificationApi.getNotifications).mockResolvedValue([]);
    vi.mocked(notificationApi.getUnreadCount).mockResolvedValue(0);
    vi.mocked(userApi.getMyPosts).mockResolvedValue([]);
    vi.mocked(userApi.getMyComments).mockResolvedValue([]);

    render(<DashboardPage />, { wrapper: createWrapper() });

    const btn = await screen.findByRole('button', { name: '查看所有评论' });
    await user.click(btn);

    expect(mockNavigate).toHaveBeenCalledWith('/dashboard/comments');
  });
});

